package in.kabadiwala.connect.integration; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.util.LinkedMultiValueMap; import org.springframework.web.client.RestClient; import java.nio.charset.StandardCharsets; import java.util.Base64; @Component @ConditionalOnProperty(name="app.sms.provider",havingValue="twilio") public class TwilioSmsProvider implements SmsProvider {private final String sid,token,from;private final RestClient c=RestClient.create();public TwilioSmsProvider(@Value("${app.sms.twilio.account-sid}")String s,@Value("${app.sms.twilio.auth-token}")String t,@Value("${app.sms.twilio.from}")String f){sid=s;token=t;from=f;}public void sendOtp(String mobile,String code,String lang){var form=new LinkedMultiValueMap<String,String>();form.add("To","+91"+mobile);form.add("From",from);form.add("Body","Kabadiwala Connect OTP: "+code+". Valid for 5 minutes.");String basic=Base64.getEncoder().encodeToString((sid+":"+token).getBytes(StandardCharsets.UTF_8));c.post().uri("https://api.twilio.com/2010-04-01/Accounts/"+sid+"/Messages.json").header("Authorization","Basic "+basic).contentType(MediaType.APPLICATION_FORM_URLENCODED).body(form).retrieve().toBodilessEntity();}public boolean exposesDevelopmentCode(){return false;}}
